python3 << 'EOF'
from PyPDF2 import PdfReader
import os

files = sorted([f for f in os.listdir('.') if f.endswith('.pdf')])
out = {}
for fn in files:
    try:
        r = PdfReader(fn)
        text = ''
        for p in r.pages[:2]:
            try:
                text += p.extract_text() + '\n'
            except:
                pass
        out[fn] = text
    except Exception as e:
        out[fn] = f'ERROR: {e}'

with open('_work/pdf_text.txt', 'w') as f:
    for fn, t in out.items():
        f.write(f'\n========== {fn} ==========\n')
        f.write(t[:4000])
        f.write('\n')
print('done', len(out))
EOF
ls -la _work/

